#!/usr/bin/env bash
# Generated by the Neutrino Translator. Proves the evidence-only PostgreSQL
# coordination against a real PostgreSQL container via docker + psql (no Python).
# It records ACCEPTED attested evidence by instance key and moves NO ledger value,
# so there are no balances/postings to assert. All dynamic SQL is fed through
# quoted heredocs, so the shell never interpolates scenario values.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
CID=$(docker run -d -e POSTGRES_PASSWORD=test -e POSTGRES_USER=test -e POSTGRES_DB=neutrino postgres:16-alpine)
cleanup(){ docker rm -f "$CID" >/dev/null 2>&1 || true; }
trap cleanup EXIT
psql(){ docker exec -i "$CID" psql -v ON_ERROR_STOP=1 -U test -d neutrino "$@"; }
echo 'waiting for postgres...'
ready=0
for _ in $(seq 1 60); do
  if psql -tAq -c 'SELECT 1' >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
[ "$ready" = 1 ] || { echo 'FAIL: postgres did not become ready'; exit 1; }

echo NEUTRINO_STAGE=compile
psql -q < "$HERE/schema.sql" >/dev/null
psql -q < "$HERE/procedure.sql" >/dev/null
echo NEUTRINO_STAGE=runtime

psql -q >/dev/null <<'SQL'
INSERT INTO authorized_observer(observer_set, observer_id) VALUES ('fixture_oracles', 'obs-1') ON CONFLICT DO NOTHING;
INSERT INTO authorized_observer(observer_set, observer_id) VALUES ('fixture_oracles', 'obs-2') ON CONFLICT DO NOTHING;
SQL

run(){ psql -tAq >/dev/null <<'SQL'
SELECT accept_core_evidence_only_milestone('ms-il-it-001-origin', 'claim-hash-1', ARRAY['obs-1', 'obs-2']);
SELECT execute_core_evidence_only_milestone('ms-il-it-001-origin', 'shipment-il-it-001', 'origin_carrier_handoff', 'shipper-il-001', 'carrier-il-001', 'sha256:1111111111111111111111111111111111111111111111111111111111111111');
SQL
}
expect_fail(){ if psql -tAq >/dev/null 2>&1; then echo "FAIL: $1 not refused"; exit 1; fi; }

# 1. quorum gate: accepting evidence without an accepted quorum is refused
expect_fail 'unaccepted execute' <<'SQL'
SELECT execute_core_evidence_only_milestone('ms-il-it-001-origin', 'shipment-il-it-001', 'origin_carrier_handoff', 'shipper-il-001', 'carrier-il-001', 'sha256:1111111111111111111111111111111111111111111111111111111111111111');
SQL
echo '  [1] quorum gate: PASS'

# 2. happy path (accept quorum + record): the accepted terminal is written; NO ledger value moves
run
A=$(psql -tAq <<'SQL'
SELECT count(*) FROM coordination_status WHERE idempotency_key='ms-il-it-001-origin' AND reconciled;
SQL
)
[ "$A" = "1" ] || { echo "FAIL: accepted=$A"; exit 1; }
echo '  [2] happy path records accepted evidence: PASS'

# 3. replay: re-recording an accepted instance key is refused
expect_fail 'replay' <<'SQL'
SELECT execute_core_evidence_only_milestone('ms-il-it-001-origin', 'shipment-il-it-001', 'origin_carrier_handoff', 'shipper-il-001', 'carrier-il-001', 'sha256:1111111111111111111111111111111111111111111111111111111111111111');
SQL
echo '  [3] replay refused: PASS'

# 4. quorum replay: re-accepting an accepted claim is refused
expect_fail 'already accepted' <<'SQL'
SELECT accept_core_evidence_only_milestone('ms-il-it-001-origin', 'claim-hash-1', ARRAY['obs-1', 'obs-2']);
SQL
echo '  [4] quorum replay refused: PASS'

# 5. instance isolation: a distinct instance key is accepted + recorded independently
psql -tAq >/dev/null <<'SQL'
SELECT accept_core_evidence_only_milestone('ms-il-it-001-origin-2', 'claim-hash-1', ARRAY['obs-1', 'obs-2']);
SELECT execute_core_evidence_only_milestone('ms-il-it-001-origin-2', 'shipment-il-it-001', 'origin_carrier_handoff', 'shipper-il-001', 'carrier-il-001', 'sha256:1111111111111111111111111111111111111111111111111111111111111111');
SQL
A2=$(psql -tAq <<'SQL'
SELECT count(*) FROM coordination_status WHERE idempotency_key='ms-il-it-001-origin-2' AND reconciled;
SQL
)
[ "$A2" = "1" ] || { echo "FAIL: isolated accepted=$A2"; exit 1; }
A1=$(psql -tAq <<'SQL'
SELECT count(*) FROM coordination_status WHERE idempotency_key='ms-il-it-001-origin' AND reconciled;
SQL
)
[ "$A1" = "1" ] || { echo "FAIL: first key disturbed=$A1"; exit 1; }
echo '  [5] instance isolation: PASS'

# 6. atomic rollback: a rolled-back accept+record leaves no rows
psql -q >/dev/null <<'SQL'
BEGIN;
SELECT accept_core_evidence_only_milestone('txn-rollback', 'claim-hash-1', ARRAY['obs-1', 'obs-2']);
SELECT execute_core_evidence_only_milestone('txn-rollback', 'shipment-il-it-001', 'origin_carrier_handoff', 'shipper-il-001', 'carrier-il-001', 'sha256:1111111111111111111111111111111111111111111111111111111111111111');
ROLLBACK;
SQL
NR=$(psql -tAq <<'SQL'
SELECT count(*) FROM coordination_status WHERE idempotency_key='txn-rollback' AND reconciled;
SQL
)
[ "$NR" = "0" ] || { echo "FAIL: rollback left rows=$NR"; exit 1; }
NQ=$(psql -tAq <<'SQL'
SELECT count(*) FROM quorum_acceptance WHERE claim_id='txn-rollback';
SQL
)
[ "$NQ" = "0" ] || { echo "FAIL: rollback left quorum rows=$NQ"; exit 1; }
echo '  [6] atomic rollback: PASS'

echo 'ALL POSTGRES CHECKS PASSED'
